/**
 * LLM skill-evaluation report.
 *
 * Unlike analysis findings (which are message codes resolved by the UI), the
 * evaluation prose is generated by the user's model in the active UI language
 * and therefore stored as plain strings.
 */
import type { LlmProvider } from './config.js';
import type { SkillRef } from './domain.js';
import type { AiVerdict } from './findings.js';

export type EvaluationIssueKind = 'duplicate' | 'conflict' | 'quality' | 'trigger' | 'boundary';

export type EvaluationSeverity = 'error' | 'warn' | 'info';

export type EvaluationGrade = 'A' | 'B' | 'C' | 'D';

export interface EvaluationSkillScore {
  skill: SkillRef;
  /** 0–100 overall quality score. */
  score: number;
  grade: EvaluationGrade;
  summary: string;
  strengths: string[];
  issues: string[];
}

/** AI judgement of one candidate skill pair. */
export interface AiPairVerdict {
  /** Unordered pair of recordKeys, used to match heuristic findings. */
  pairKey: string;
  skills: [SkillRef, SkillRef];
  kind: EvaluationIssueKind;
  verdict: AiVerdict;
  severity: EvaluationSeverity;
  title: string;
  detail: string;
  suggestion: string | null;
}

export interface EvaluationReport {
  generatedAt: string;
  provider: LlmProvider;
  model: string;
  /** Language the prose was generated in. */
  locale: 'zh' | 'en';
  /**
   * Fingerprint of the evaluated input (skill content hashes + model). Used to
   * flag the report as stale when skills change; it never hides the report.
   */
  signature: string;
  summary: string;
  averageScore: number;
  scores: EvaluationSkillScore[];
}

/** Persisted together in `evaluation.json`. */
export interface EvaluationStore {
  report: EvaluationReport | null;
  verdicts: AiPairVerdict[];
  verdictsAt: string | null;
  /** Input fingerprint of the reviewed candidates; flags verdicts as stale. */
  verdictsSignature: string | null;
}

/** Progress of a running evaluation, streamed to the UI as batches complete. */
export interface EvaluationProgress {
  done: number;
  total: number;
}

/** Translatable step labels for the live process log. */
export type EvaluationStepCode =
  | 'eval.step.prepare'
  | 'eval.step.scoring'
  | 'eval.step.pairs'
  | 'eval.step.judging'
  | 'eval.step.summary'
  | 'eval.step.review';

export interface EvaluationStep {
  code: EvaluationStepCode;
  params?: Record<string, string | number>;
}

/**
 * Transient process events streamed to the UI while an evaluation runs. They
 * are never persisted: only the final report is written to disk.
 */
export interface EvaluationEvent {
  type: 'start' | 'step' | 'reasoning' | 'done';
  step?: EvaluationStep;
  /** Model reasoning delta, when the provider exposes one. */
  text?: string;
}
